    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_step(v):
        if v > 1:
            return 1
        if v < -1:
            return -1
        return int(v)

    def add_target(targets, pos, weight=1):
